fn multisig_post_operation(
    summary: &str,
    description: &str,
    request_schema_ref: &str,
    response_schema_ref: &str,
    not_found_description: &str,
) -> Map {
    let mut operation = Map::new();
    operation.insert(
        "tags".into(),
        Value::Array(vec![Value::String("Multisig".to_owned())]),
    );
    operation.insert("summary".into(), Value::String(summary.to_owned()));
    operation.insert("description".into(), Value::String(description.to_owned()));
    operation.insert(
        "requestBody".into(),
        Value::Object(json_or_norito_request_body(request_schema_ref)),
    );
    let mut responses = single_json_response(response_schema_ref);
    responses.insert(
        "400".to_owned(),
        json_response(
            "Invalid multisig selector or payload.",
            error_schema_reference(),
        ),
    );
    responses.insert(
        "404".to_owned(),
        json_response(not_found_description, error_schema_reference()),
    );
    operation.insert("responses".into(), Value::Object(responses));
    let mut methods = Map::new();
    methods.insert("post".to_owned(), Value::Object(operation));
    methods
}

fn multisig_authenticated_read_operation(
    summary: &str,
    description: &str,
    request_schema_ref: &str,
    response_schema_ref: &str,
    not_found_description: &str,
    parameters: Vec<Value>,
    include_not_found: bool,
    include_auth_unavailable: bool,
) -> Map {
    let mut methods = multisig_post_operation(
        summary,
        description,
        request_schema_ref,
        response_schema_ref,
        not_found_description,
    );
    let post = methods
        .get_mut("post")
        .and_then(Value::as_object_mut)
        .expect("multisig POST operation");
    post.insert("parameters".into(), Value::Array(parameters));
    let responses = post
        .get_mut("responses")
        .and_then(Value::as_object_mut)
        .expect("multisig POST responses");
    if !include_not_found {
        responses.remove("404");
    }
    responses.insert(
        "403".to_owned(),
        json_response(
            "The authenticated viewer or signed caller is not allowed to access this multisig approval.",
            error_schema_reference(),
        ),
    );
    if include_auth_unavailable {
        responses.insert(
            "401".to_owned(),
            json_response(
                "The Authorization bearer token is missing or invalid.",
                error_schema_reference(),
            ),
        );
        responses.insert(
            "503".to_owned(),
            json_response(
                "JWT viewer authentication is not configured on this Torii instance.",
                error_schema_reference(),
            ),
        );
    }
    methods
}

fn multisig_jwt_read_operation(
    summary: &str,
    description: &str,
    request_schema_ref: &str,
    response_schema_ref: &str,
    not_found_description: &str,
    include_not_found: bool,
) -> Map {
    multisig_authenticated_read_operation(
        summary,
        description,
        request_schema_ref,
        response_schema_ref,
        not_found_description,
        vec![string_header_param(
            "Authorization",
            "Required bearer JWT whose canonical subject and dataspace claims define the viewer scope.",
            true,
        )],
        include_not_found,
        true,
    )
}

fn multisig_signed_read_operation(
    summary: &str,
    description: &str,
    request_schema_ref: &str,
    response_schema_ref: &str,
    not_found_description: &str,
    include_not_found: bool,
) -> Map {
    multisig_authenticated_read_operation(
        summary,
        description,
        request_schema_ref,
        response_schema_ref,
        not_found_description,
        vec![
            string_header_param(
                "X-Iroha-Account",
                "Canonical caller AccountId bound into the exact request signature.",
                true,
            ),
            string_header_param(
                "X-Iroha-Signature",
                "Canonical signature over method, URI, exact request bytes, timestamp, and nonce.",
                true,
            ),
            string_header_param(
                "X-Iroha-Timestamp-Ms",
                "Signed Unix timestamp in milliseconds.",
                true,
            ),
            string_header_param("X-Iroha-Nonce", "Signed replay-protection nonce.", true),
        ],
        include_not_found,
        false,
    )
}

