    #[test]
    fn multisig_propose_documents_native_norito_request_body() {
        let doc = generate_spec();
        let paths = doc
            .get("paths")
            .and_then(Value::as_object)
            .expect("paths section");
        let propose = paths
            .get("/v1/multisig/propose")
            .and_then(Value::as_object)
            .expect("multisig propose path");
        let post = propose
            .get("post")
            .and_then(Value::as_object)
            .expect("post operation");
        let request_body = post
            .get("requestBody")
            .and_then(Value::as_object)
            .expect("request body");
        let content = request_body
            .get("content")
            .and_then(Value::as_object)
            .expect("request content");
        assert!(content.contains_key("application/json"));
        assert!(content.contains_key("application/x-norito"));

        let norito_schema_type = content
            .get("application/x-norito")
            .and_then(Value::as_object)
            .and_then(|media| media.get("schema"))
            .and_then(Value::as_object)
            .and_then(|schema| schema.get("type"))
            .and_then(Value::as_str);
        assert_eq!(norito_schema_type, Some("string"));

        let schemas = doc
            .get("components")
            .and_then(Value::as_object)
            .and_then(|components| components.get("schemas"))
            .and_then(Value::as_object)
            .expect("schemas");
        let instruction_schema_ref = schemas
            .get("MultisigProposeRequest")
            .and_then(Value::as_object)
            .and_then(|request| request.get("allOf"))
            .and_then(Value::as_array)
            .and_then(|all_of| all_of.get(1))
            .and_then(Value::as_object)
            .and_then(|payload| payload.get("properties"))
            .and_then(Value::as_object)
            .and_then(|properties| properties.get("instructions"))
            .and_then(Value::as_object)
            .and_then(|instructions| instructions.get("items"))
            .and_then(Value::as_object)
            .and_then(|items| items.get("$ref"))
            .and_then(Value::as_str);
        assert_eq!(
            instruction_schema_ref,
            Some("#/components/schemas/MultisigProposeInstructionInput")
        );

        let instruction_input = schemas
            .get("MultisigProposeInstructionInput")
            .and_then(Value::as_object)
            .expect("instruction input schema");
        assert_eq!(
            instruction_input.get("type").and_then(Value::as_str),
            Some("object")
        );
        assert!(
            !instruction_input.contains_key("oneOf"),
            "JSON instructions must not advertise per-instruction Norito blobs"
        );
        assert!(
            instruction_input
                .get("description")
                .and_then(Value::as_str)
                .is_some_and(
                    |description| description.contains("entire MultisigProposeRequest body")
                ),
            "instruction schema should direct native callers to whole-body Norito"
        );
    }

    #[test]
    fn multisig_proposal_schemas_document_status_filters_and_lifecycle_fields() {
        let doc = generate_spec();
        assert_eq!(doc.get("openapi").and_then(Value::as_str), Some("3.1.0"));
        let schemas = doc
            .get("components")
            .and_then(Value::as_object)
            .and_then(|components| components.get("schemas"))
            .and_then(Value::as_object)
            .expect("components schemas");

        let query_request = schemas
            .get("MultisigProposalsQueryRequest")
            .and_then(Value::as_object)
            .expect("multisig proposals query request schema");
        assert_eq!(
            query_request
                .get("additionalProperties")
                .and_then(Value::as_bool),
            Some(false)
        );
        let query_properties = query_request
            .get("properties")
            .and_then(Value::as_object)
            .expect("multisig proposals query request properties");
        let status_schema = query_properties
            .get("status")
            .and_then(Value::as_object)
            .expect("proposal status filter schema");
        assert_eq!(
            status_schema.get("maxItems").and_then(Value::as_u64),
            Some(4)
        );
        assert_eq!(
            status_schema.get("uniqueItems").and_then(Value::as_bool),
            Some(true)
        );
        let request_status = status_schema
            .get("items")
            .and_then(Value::as_object)
            .and_then(|items| items.get("enum"))
            .and_then(Value::as_array)
            .expect("proposal status filter enum");
        let expected_request_status =
            norito::json!(["COLLECTING_SIGNATURES", "FINALIZED", "CANCELED", "EXPIRED"]);
        assert_eq!(
            request_status,
            expected_request_status
                .as_array()
                .expect("expected proposal status enum array")
        );

        let non_null_option = |field: &str| {
            query_properties
                .get(field)
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("oneOf"))
                .and_then(Value::as_array)
                .and_then(|alternatives| {
                    alternatives.iter().find_map(|alternative| {
                        alternative.as_object().filter(|schema| {
                            schema.get("type").and_then(Value::as_str) != Some("null")
                        })
                    })
                })
                .unwrap_or_else(|| panic!("proposal query {field} non-null schema"))
        };
        let limit = non_null_option("limit");
        assert_eq!(limit.get("minimum").and_then(Value::as_u64), Some(1));
        assert_eq!(
            limit.get("maximum").and_then(Value::as_u64),
            Some(crate::routing::MULTISIG_PROPOSALS_MAX_PAGE_LIMIT)
        );
        let cursor = non_null_option("cursor");
        assert_eq!(cursor.get("maxLength").and_then(Value::as_u64), Some(512));
        for field in ["cursor", "limit"] {
            assert!(
                query_properties
                    .get(field)
                    .and_then(Value::as_object)
                    .and_then(|schema| schema.get("oneOf"))
                    .and_then(Value::as_array)
                    .is_some_and(|alternatives| alternatives.iter().any(|alternative| {
                        alternative.get("type").and_then(Value::as_str) == Some("null")
                    }))
            );
        }

        for request_name in [
            "MultisigSpecRequest",
            "MultisigProposalsQueryRequest",
            "MultisigProposalLookupRequest",
        ] {
            let request = schemas
                .get(request_name)
                .and_then(Value::as_object)
                .unwrap_or_else(|| panic!("{request_name} schema"));
            assert_eq!(
                request.get("additionalProperties").and_then(Value::as_bool),
                Some(false),
                "{request_name} must reject unknown top-level fields"
            );
            let properties = request
                .get("properties")
                .and_then(Value::as_object)
                .expect("closed request properties");
            assert!(properties.contains_key("multisig_account_id"));
            assert!(properties.contains_key("multisig_account_alias"));
            assert!(
                properties
                    .get("multisig_account_id")
                    .and_then(Value::as_object)
                    .is_some_and(|schema| !schema.contains_key("maxLength")),
                "{request_name} must allow native multisig AccountIds up to the request-body limit"
            );
        }

        let lookup_request = schemas
            .get("MultisigProposalLookupRequest")
            .and_then(Value::as_object)
            .expect("multisig proposal lookup request schema");
        assert_eq!(
            lookup_request
                .get("allOf")
                .and_then(Value::as_array)
                .map(Vec::len),
            Some(2),
            "lookup must require one authority selector and one proposal selector"
        );

        let query_response = schemas
            .get("MultisigProposalsQueryResponse")
            .and_then(Value::as_object)
            .and_then(|schema| schema.get("properties"))
            .and_then(Value::as_object)
            .expect("multisig proposal query response properties");
        assert_eq!(
            query_response
                .get("proposals")
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("maxItems"))
                .and_then(Value::as_u64),
            Some(crate::routing::MULTISIG_PROPOSALS_MAX_PAGE_LIMIT)
        );
        assert!(query_response.contains_key("next_cursor"));

        let nullable_intent_schema = norito::json!({ "$ref": "#/components/schemas/JsonValue" });
        let nullable_terminal_timestamp_schema = norito::json!({
            "oneOf": [
                { "type": "integer", "format": "uint64" },
                { "type": "null" }
            ]
        });
        for schema_name in ["MultisigProposalEntry", "MultisigProposalLookupResponse"] {
            let schema = schemas
                .get(schema_name)
                .and_then(Value::as_object)
                .unwrap_or_else(|| panic!("{schema_name} schema"));
            let required = schema
                .get("required")
                .and_then(Value::as_array)
                .expect("required fields");
            for field in ["operation_type", "proposal", "status"] {
                assert!(
                    required.iter().any(|value| value.as_str() == Some(field)),
                    "{schema_name} must require {field}"
                );
            }
            let properties = schema
                .get("properties")
                .and_then(Value::as_object)
                .expect("proposal properties");
            assert_eq!(
                properties.get("intent"),
                Some(&nullable_intent_schema),
                "{schema_name}.intent must use the null-capable JsonValue schema without the retired OpenAPI 3.0 nullable keyword"
            );
            assert_eq!(
                properties.get("terminal_at_ms"),
                Some(&nullable_terminal_timestamp_schema),
                "{schema_name}.terminal_at_ms must explicitly model integer-or-null under OpenAPI 3.1"
            );
            let status_values = properties
                .get("status")
                .and_then(Value::as_object)
                .and_then(|status| status.get("enum"))
                .and_then(Value::as_array)
                .expect("proposal response status enum");
            assert_eq!(status_values, request_status);
        }
    }

    #[test]
    fn multisig_approval_paths_use_viewer_scoped_typed_query_and_lookup_contracts() {
        fn operation<'a>(paths: &'a Map, path: &str) -> &'a Map {
            paths
                .get(path)
                .and_then(Value::as_object)
                .and_then(|path| path.get("post"))
                .and_then(Value::as_object)
                .unwrap_or_else(|| panic!("missing multisig approval operation {path}"))
        }

        fn request_schema_ref<'a>(operation: &'a Map) -> &'a str {
            operation
                .get("requestBody")
                .and_then(Value::as_object)
                .and_then(|body| body.get("content"))
                .and_then(Value::as_object)
                .and_then(|content| content.get("application/json"))
                .and_then(Value::as_object)
                .and_then(|media| media.get("schema"))
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("$ref"))
                .and_then(Value::as_str)
                .expect("multisig approval request schema reference")
        }

        fn response_schema_ref<'a>(operation: &'a Map) -> &'a str {
            operation
                .get("responses")
                .and_then(Value::as_object)
                .and_then(|responses| responses.get("200"))
                .and_then(Value::as_object)
                .and_then(|response| response.get("content"))
                .and_then(Value::as_object)
                .and_then(|content| content.get("application/json"))
                .and_then(Value::as_object)
                .and_then(|media| media.get("schema"))
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("$ref"))
                .and_then(Value::as_str)
                .expect("multisig approval response schema reference")
        }

        let doc = generate_spec();
        let paths = doc
            .get("paths")
            .and_then(Value::as_object)
            .expect("paths section");
        let schemas = doc
            .get("components")
            .and_then(Value::as_object)
            .and_then(|components| components.get("schemas"))
            .and_then(Value::as_object)
            .expect("components schemas");

        for path in [
            "/v1/multisig/approvals/query",
            "/v1/multisig/approvals/query-for-authority",
        ] {
            let operation = operation(paths, path);
            assert_eq!(
                request_schema_ref(operation),
                "#/components/schemas/MultisigApprovalsQueryRequest"
            );
            assert_eq!(
                response_schema_ref(operation),
                "#/components/schemas/MultisigApprovalsQueryResponse"
            );
        }
        for path in [
            "/v1/multisig/approvals/lookup",
            "/v1/multisig/approvals/lookup-for-authority",
        ] {
            let operation = operation(paths, path);
            assert_eq!(
                request_schema_ref(operation),
                "#/components/schemas/MultisigApprovalLookupRequest"
            );
            assert_eq!(
                response_schema_ref(operation),
                "#/components/schemas/MultisigApprovalLookupResponse"
            );
        }
        for path in [
            "/v1/multisig/approvals/query",
            "/v1/multisig/approvals/lookup",
        ] {
            let operation = operation(paths, path);
            assert!(
                operation
                    .get("description")
                    .and_then(Value::as_str)
                    .is_some_and(|description| description.contains("JWT viewer scope")),
                "{path} must document JWT viewer scoping"
            );
            let parameters = operation
                .get("parameters")
                .and_then(Value::as_array)
                .expect("JWT approvals parameters");
            assert!(parameters.iter().any(|parameter| {
                parameter
                    .get("name")
                    .and_then(Value::as_str)
                    .is_some_and(|name| name == "Authorization")
                    && parameter.get("required").and_then(Value::as_bool) == Some(true)
            }));
            let responses = operation
                .get("responses")
                .and_then(Value::as_object)
                .expect("JWT approvals responses");
            for status in ["401", "403", "503"] {
                assert!(
                    responses.contains_key(status),
                    "{path} must document {status}"
                );
            }
            assert_eq!(responses.contains_key("404"), path.ends_with("/lookup"));
        }
        for path in [
            "/v1/multisig/approvals/query-for-authority",
            "/v1/multisig/approvals/lookup-for-authority",
        ] {
            let operation = operation(paths, path);
            assert!(
                operation
                    .get("description")
                    .and_then(Value::as_str)
                    .is_some_and(|description| {
                        description.contains("exact HTTP request signature")
                            && description.contains("caller authority")
                    }),
                "{path} must document exact signed caller-authority scoping"
            );
            let parameters = operation
                .get("parameters")
                .and_then(Value::as_array)
                .expect("signed approvals parameters");
            for header in [
                "X-Iroha-Account",
                "X-Iroha-Signature",
                "X-Iroha-Timestamp-Ms",
                "X-Iroha-Nonce",
            ] {
                assert!(parameters.iter().any(|parameter| {
                    parameter.get("name").and_then(Value::as_str) == Some(header)
                        && parameter.get("required").and_then(Value::as_bool) == Some(true)
                }));
            }
            let responses = operation
                .get("responses")
                .and_then(Value::as_object)
                .expect("signed approvals responses");
            assert!(responses.contains_key("403"));
            assert_eq!(
                responses.contains_key("404"),
                path.ends_with("/lookup-for-authority")
            );
        }

        for retired_name in [
            "MultisigProposalsListRequest",
            "MultisigProposalsListResponse",
            "MultisigProposalsGetRequest",
            "MultisigProposalGetResponse",
            "MultisigApprovalsListRequest",
            "MultisigApprovalsListResponse",
            "MultisigApprovalsGetRequest",
            "MultisigApprovalsGetResponse",
        ] {
            assert!(
                !schemas.contains_key(retired_name),
                "retired first-release component alias {retired_name} must not be emitted"
            );
        }

        let query_request = schemas
            .get("MultisigApprovalsQueryRequest")
            .and_then(Value::as_object)
            .expect("multisig approvals query request");
        assert_eq!(
            query_request
                .get("additionalProperties")
                .and_then(Value::as_bool),
            Some(false)
        );
        let query_properties = query_request
            .get("properties")
            .and_then(Value::as_object)
            .expect("multisig approvals query properties");
        assert_eq!(query_properties.len(), 5);
        for field in [
            "status",
            "operation_type",
            "requires_my_signature",
            "cursor",
            "limit",
        ] {
            assert!(query_properties.contains_key(field));
        }
        assert!(!query_properties.contains_key("multisig_account_id"));
        assert!(!query_properties.contains_key("multisig_account_alias"));
        let operation_type_filter = query_properties
            .get("operation_type")
            .and_then(Value::as_object)
            .and_then(|schema| schema.get("items"))
            .and_then(Value::as_object)
            .expect("operation_type filter item schema");
        assert_eq!(
            operation_type_filter
                .get("maxLength")
                .and_then(Value::as_u64),
            Some(128)
        );
        assert_eq!(
            operation_type_filter.get("pattern").and_then(Value::as_str),
            Some("^[A-Z][A-Z0-9_]*$")
        );
        for field in ["cursor", "limit"] {
            let alternatives = query_properties
                .get(field)
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("oneOf"))
                .and_then(Value::as_array)
                .unwrap_or_else(|| panic!("{field} must be explicitly nullable"));
            assert!(alternatives.iter().any(|alternative| {
                alternative
                    .as_object()
                    .and_then(|schema| schema.get("type"))
                    .and_then(Value::as_str)
                    == Some("null")
            }));
        }

        let lookup_request = schemas
            .get("MultisigApprovalLookupRequest")
            .and_then(Value::as_object)
            .expect("multisig approval lookup request");
        assert_eq!(
            lookup_request
                .get("additionalProperties")
                .and_then(Value::as_bool),
            Some(false)
        );
        let lookup_required = lookup_request
            .get("required")
            .and_then(Value::as_array)
            .expect("approval lookup required fields");
        let expected_lookup_required = norito::json!(["multisig_account_ref"]);
        assert_eq!(
            lookup_required,
            expected_lookup_required
                .as_array()
                .expect("expected approval lookup required fields")
        );
        assert_eq!(
            lookup_request
                .get("oneOf")
                .and_then(Value::as_array)
                .map(Vec::len),
            Some(2),
            "approval lookup must accept exactly one proposal selector"
        );
        let lookup_properties = lookup_request
            .get("properties")
            .and_then(Value::as_object)
            .expect("approval lookup properties");
        assert_eq!(lookup_properties.len(), 3);
        assert!(!lookup_properties.contains_key("multisig_account_alias"));
        assert_eq!(
            lookup_properties
                .get("multisig_account_ref")
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("pattern"))
                .and_then(Value::as_str),
            Some("^[0-9a-f]{64}$")
        );

        let entry = schemas
            .get("MultisigApprovalEntry")
            .and_then(Value::as_object)
            .expect("multisig approval entry");
        let entry_required = entry
            .get("required")
            .and_then(Value::as_array)
            .expect("multisig approval entry required fields");
        for field in [
            "multisig_account_id",
            "multisig_account_ref",
            "spec",
            "proposal_id",
            "instructions_hash",
            "proposal",
            "operation_type",
            "status",
        ] {
            assert!(
                entry_required
                    .iter()
                    .any(|value| value.as_str() == Some(field))
            );
        }
        for field in ["intent", "terminal_at_ms"] {
            assert!(
                !entry_required
                    .iter()
                    .any(|value| value.as_str() == Some(field))
            );
        }
        assert!(
            entry
                .get("properties")
                .and_then(Value::as_object)
                .and_then(|properties| properties.get("multisig_account_id"))
                .and_then(Value::as_object)
                .is_some_and(|schema| !schema.contains_key("maxLength"))
        );
        let entry_operation_type = entry
            .get("properties")
            .and_then(Value::as_object)
            .and_then(|properties| properties.get("operation_type"))
            .and_then(Value::as_object)
            .expect("approval entry operation_type schema");
        assert_eq!(
            entry_operation_type.get("pattern").and_then(Value::as_str),
            Some("^[A-Z][A-Z0-9_]*$")
        );

        let query_response = schemas
            .get("MultisigApprovalsQueryResponse")
            .and_then(Value::as_object)
            .expect("multisig approvals query response");
        assert_eq!(
            query_response
                .get("properties")
                .and_then(Value::as_object)
                .and_then(|properties| properties.get("items"))
                .and_then(Value::as_object)
                .and_then(|items| items.get("items"))
                .and_then(Value::as_object)
                .and_then(|items| items.get("$ref"))
                .and_then(Value::as_str),
            Some("#/components/schemas/MultisigApprovalEntry")
        );
        assert!(
            query_response
                .get("properties")
                .and_then(Value::as_object)
                .is_some_and(|properties| properties.contains_key("next_cursor"))
        );
        assert_eq!(
            schemas
                .get("MultisigApprovalLookupResponse")
                .and_then(Value::as_object)
                .and_then(|schema| schema.get("properties"))
                .and_then(Value::as_object)
                .and_then(|properties| properties.get("item"))
                .and_then(Value::as_object)
                .and_then(|item| item.get("$ref"))
                .and_then(Value::as_str),
            Some("#/components/schemas/MultisigApprovalEntry")
        );
    }

    #[test]
    #[allow(clippy::similar_names)]
    fn helper_builders_emit_expected_shapes() {
        let body = binary_request_body("binary payload");
        let body_obj = body.as_object().expect("binary request body object");
        assert_eq!(
            body_obj.get("description").and_then(Value::as_str),
            Some("binary payload")
        );
        let content = body_obj
            .get("content")
            .and_then(Value::as_object)
            .expect("binary request body content");
        assert!(content.contains_key("application/x-norito"));
        assert!(!content.contains_key("application/octet-stream"));

        let response = binary_response("binary response");
        let response_obj = response.as_object().expect("binary response object");
        assert_eq!(
            response_obj.get("description").and_then(Value::as_str),
            Some("binary response")
        );
        let response_content = response_obj
            .get("content")
            .and_then(Value::as_object)
            .expect("binary response content");
        assert!(response_content.contains_key("application/octet-stream"));

        let param = string_path_param("item", "Item id.");
        let param_obj = param.as_object().expect("string param object");
        assert_eq!(param_obj.get("name").and_then(Value::as_str), Some("item"));
        let int_param = integer_path_param("height", "Height.", Some("uint64"));
        let int_param_obj = int_param.as_object().expect("integer param object");
        let schema = int_param_obj
            .get("schema")
            .and_then(Value::as_object)
            .expect("integer schema");
        assert_eq!(schema.get("format").and_then(Value::as_str), Some("uint64"));

        let get_op = json_get_operation(
            "System",
            "Summary",
            "Description",
            "#/components/schemas/JsonValue",
            vec![string_path_param("id", "Identifier.")],
        );
        assert!(get_op.contains_key("get"));

        let post_op = json_post_operation(
            "System",
            "Summary",
            "Description",
            "#/components/schemas/JsonValue",
            "#/components/schemas/JsonValue",
            Vec::new(),
        );
        let post_operation = post_op
            .get("post")
            .and_then(Value::as_object)
            .expect("post operation");
        let post_body = post_operation
            .get("requestBody")
            .and_then(Value::as_object)
            .expect("post request body");
        let post_content = post_body
            .get("content")
            .and_then(Value::as_object)
            .expect("post request body content");
        assert!(post_content.contains_key("application/json"));

        let delete_op = json_delete_operation(
            "System",
            "Summary",
            "Description",
            "#/components/schemas/JsonValue",
            Vec::new(),
        );
        assert!(delete_op.contains_key("delete"));

        let text_op = text_get_operation("System", "Summary", "Description", Some("example"));
        let text_get = text_op
            .get("get")
            .and_then(Value::as_object)
            .expect("text get operation");
        let text_responses = text_get
            .get("responses")
            .and_then(Value::as_object)
            .expect("text responses");
        let text_ok = text_responses
            .get("200")
            .and_then(Value::as_object)
            .expect("text ok response");
        let text_content = text_ok
            .get("content")
            .and_then(Value::as_object)
            .expect("text response content");
        assert!(text_content.contains_key("text/plain"));

        let sse_op = event_stream_get_operation("Streams", "Summary", "Description");
        let sse_get = sse_op
            .get("get")
            .and_then(Value::as_object)
            .expect("sse get operation");
        let sse_responses = sse_get
            .get("responses")
            .and_then(Value::as_object)
            .expect("sse responses");
        let sse_ok = sse_responses
            .get("200")
            .and_then(Value::as_object)
            .expect("sse ok response");
        let sse_content = sse_ok
            .get("content")
            .and_then(Value::as_object)
            .expect("sse response content");
        assert!(sse_content.contains_key("text/event-stream"));

        let binary_post = binary_post_operation(
            "Transactions",
            "Submit",
            "Description",
            "#/components/schemas/JsonValue",
        );
        let binary_operation = binary_post
            .get("post")
            .and_then(Value::as_object)
            .expect("binary post operation");
        let binary_body = binary_operation
            .get("requestBody")
            .and_then(Value::as_object)
            .expect("binary request body");
        let binary_content = binary_body
            .get("content")
            .and_then(Value::as_object)
            .expect("binary request content");
        assert!(binary_content.contains_key("application/x-norito"));
    }

